// ❌ Task starvation — blocks rendering
function heavyWork() {
  let start = performance.now();
  while (performance.now() - start < 100) {
    // busy for 100ms — blocks rendering!
  }
  console.log("done");
}

// ✅ Chunked work with rAF
function chunkedWork(items, chunkSize = 100) {
  let index = 0;
  function processChunk() {
    let end = Math.min(index + chunkSize, items.length);
    for (; index < end; index++) {
      // process item
    }
    if (index < items.length) {
      requestAnimationFrame(processChunk);  // yield to rendering
    }
  }
  requestAnimationFrame(processChunk);
}
